import { Group, Mesh, BoxGeometry, PlaneGeometry, MeshPhysicalNodeMaterial, MeshBasicNodeMaterial, MeshStandardNodeMaterial, DirectionalLight, Color } from 'three/webgpu';
import { uv, vec2, vec3, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitivesLib from '@/primitives';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'stat-tile-collection';

  const timelines = [];
  const primitiveHandles = [];
  const disposables = [];

  // --- depth plane 1: backdrop plate (machined ink) ---
  const backdropGeo = new BoxGeometry(1.85, 1.35, 0.05);
  const backdropMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.ink),
    roughness: 0.6,
    metalness: 0.4,
    clearcoat: 0.15,
    clearcoatRoughness: 0.4,
  });
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -0.08);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // --- depth plane 2: main card (machined surface) ---
  const cardGeo = new BoxGeometry(1.6, 1.1, 0.12);
  const cardMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.surface),
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
  });
  const card = new Mesh(cardGeo, cardMat);
  card.position.set(0, 0, 0);
  root.add(card);
  disposables.push(cardGeo, cardMat);

  // --- depth plane 3: foreground accent bar (signal red rim) ---
  const accentGeo = new BoxGeometry(1.6, 0.06, 0.02);
  const accentMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    emissive: new Color(colors.accent),
    emissiveIntensity: 1.6,
    roughness: 0.4,
    metalness: 0.2,
  });
  const accentBar = new Mesh(accentGeo, accentMat);
  accentBar.position.set(0, -0.47, 0.075);
  root.add(accentBar);
  disposables.push(accentGeo, accentMat);

  // --- radial contact shadow beneath tile ---
  const shadowGeo = new PlaneGeometry(2.2, 1.8);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const uvNode = uv();
  const dist = uvNode.sub(vec2(0.5, 0.5)).length();
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = smoothstep(0.5, 0.0, dist).mul(0.45);
  const shadowPlane = new Mesh(shadowGeo, shadowMat);
  shadowPlane.position.set(0, -0.05, -0.6);
  root.add(shadowPlane);
  disposables.push(shadowGeo, shadowMat);

  // --- local rim light (accent hue, opposite key) ---
  const rimLight = new DirectionalLight(new Color(colors.accent), 0.8);
  rimLight.position.set(-1.5, 0.8, 1.2);
  root.add(rimLight);

  // --- decorative machined gear mesh (metric ornament) ---
  const gearGroup = new Group();
  gearGroup.position.set(0.55, 0.15, 0.14);
  gearGroup.scale.setScalar(0.28);
  root.add(gearGroup);

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const scene = gltf.scene ?? gltf;
      gearGroup.add(scene);
      scene.traverse((child) => {
        if (child.isMesh && child.material) {
          child.material.roughness = Math.max(child.material.roughness ?? 0.5, 0.5);
          child.material.metalness = Math.min(child.material.metalness ?? 0.5, 0.55);
        }
      });
    }).catch(() => {});
  }

  // idle slow rotation on the gear ornament (single slow transform)
  const idleTl = gsap.timeline({ repeat: -1 });
  idleTl.to(gearGroup.rotation, { z: Math.PI * 2, duration: 24, ease: 'none' });
  timelines.push(idleTl);

  // --- text content (value + label) rendered from spec only if present ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textNodes = [];
  for (const item of items) {
    if (!item?.text) continue;
    const isValue = item.role === 'metric-value' || item.role === 'value';
    const opts = isValue
      ? { fontSize: 62, color: colors.paper, align: 'center' }
      : { fontSize: 18, color: colors.paper, align: 'center', letterSpacingPx: 2 };
    const textObj = ctx.fontAtlas.createText(String(item.text), opts);
    textObj.position.set(0, isValue ? 0.18 : -0.2, 0.09);
    root.add(textObj);
    textNodes.push(textObj);
  }

  // --- entrance: weighted-settle ---
  root.scale.setScalar(0.001);
  const entranceTl = gsap.timeline();
  entranceTl.to(root.scale, {
    x: 1.04, y: 1.04, z: 1.04,
    duration: 0.55,
    ease: 'power3.out',
  }).to(root.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });
  timelines.push(entranceTl);

  // --- cinematic primitives (mandatory application) ---
  for (const prim of config.cinematicPrimitives ?? []) {
    if (typeof ctx.primitives[prim.name] === 'function') {
      const handle = ctx.primitives[prim.name](root, prim.params ?? {});
      primitiveHandles.push(handle);
    }
  }

  // --- hover / click interaction handlers ---
  let hoverTl = null;
  const baseY = root.position.y;

  const onHoverStart = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, {
      y: baseY + 0.15,
      duration: 0.3,
      ease: 'power2.out',
    });
    timelines.push(hoverTl);
  };

  const onHoverEnd = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, {
      y: baseY,
      duration: 0.3,
      ease: 'power2.out',
    });
    timelines.push(hoverTl);
  };

  const onClick = () => {
    const pressTl = gsap.timeline();
    pressTl.to(root.scale, {
      x: 0.97, y: 0.97, z: 0.97,
      duration: 0.12,
      ease: 'back.out',
    }).to(root.scale, {
      x: 1, y: 1, z: 1,
      duration: 0.2,
      ease: 'power2.out',
    });
    timelines.push(pressTl);
    ctx.emit('hub-collection.select', { source: 'stat-tile', targetInput: 'trpc.waitlist.join.input.email' });
  };

  root.userData.handlers = {
    onHoverStart,
    onHoverEnd,
    onClick,
  };

  // --- cleanup ---
  root.userData.cleanup = () => {
    for (const tl of timelines) {
      tl.kill();
    }
    timelines.length = 0;

    for (const handle of primitiveHandles) {
      handle?.cleanup?.();
    }
    primitiveHandles.length = 0;

    for (const obj of textNodes) {
      obj.traverse?.((child) => {
        child.geometry?.dispose?.();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose?.());
          } else {
            child.material.dispose?.();
          }
        }
      });
      root.remove(obj);
    }

    for (const res of disposables) {
      res?.dispose?.();
    }

    rimLight.dispose?.();

    gearGroup.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose?.();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose?.());
          } else {
            child.material.dispose?.();
          }
        }
      }
    });
  };

  return root;
}
